<?php
require_once 'conexion.php';if(($_SERVER['REQUEST_METHOD']??'')!=='DELETE'){http_response_code(405);exit('Método no permitido.');}$id=filter_var($_GET['id']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false){http_response_code(422);exit('<div class="notification is-danger">Medicamento no válido.</div>');}
try{$s=$pdo->prepare('DELETE FROM dbo.medicamento WHERE id_medicamento=?');$s->execute([$id]);if(!$s->rowCount()){http_response_code(404);exit('<div class="notification is-warning">El medicamento no existe.</div>');}header('HX-Trigger: medicamentoEliminado');echo '<div class="notification is-success">Medicamento eliminado.</div>';}catch(PDOException $e){http_response_code(409);echo '<div class="notification is-danger">No se puede eliminar: el medicamento puede tener lotes, compras o ventas asociadas.</div>';}
